5	// Converts an absolute file path into the POSIX-relative blob key
6	// convention shared with the server (relative to baseDir, "/"-separated
7	// regardless of host path separator).
8	function toKey(fullPath, baseDir) {
9	  return path.relative(baseDir, fullPath).split(path.sep).join('/');
10	}
11	
12	// Percent-encodes each path segment independently so a literal "/" in the
13	// key is preserved as a path separator, matching the server's per-segment
14	// decodeURIComponent in parseBlobKey.
15	function encodeKeyForUrl(key) {
16	  return key.split('/').map(encodeURIComponent).join('/');
17	}
18	
19	module.exports = { toKey, encodeKeyForUrl };
